from typing import Any


def validate_action(action: str) -> bool:
    return action in {"read_item", "write_item", "delete_item"}


def normalize_key(payload: dict[str, Any]) -> str:
    return str(payload.get("key", "")).strip()


def normalize_value(payload: dict[str, Any]) -> str:
    return str(payload.get("value", "")).strip()


def build_read_output(key: str, item: dict[str, Any]) -> dict[str, Any]:
    return {"key": key, "item": dict(item), "found": True}


def build_missing_output(key: str) -> dict[str, Any]:
    return {"key": key, "item": {}, "found": False}


def build_write_output(key: str, value: str, user_id: str) -> dict[str, Any]:
    return {"key": key, "value": value, "updated_by": user_id}


def build_delete_output(key: str, deleted: bool) -> dict[str, Any]:
    return {"key": key, "deleted": deleted}


def validate_write_payload(payload: dict[str, Any]) -> tuple[bool, str]:
    key = normalize_key(payload)
    value = normalize_value(payload)
    if not key:
        return (False, "invalid_key")
    if not value:
        return (False, "invalid_value")
    return (True, "ok")


def can_delete(allow_delete: bool) -> bool:
    return bool(allow_delete)


def is_read_action(action: str) -> bool:
    return action == "read_item"


def is_write_action(action: str) -> bool:
    return action == "write_item"


def is_delete_action(action: str) -> bool:
    return action == "delete_item"


def summarize_action_result(ok: bool, reason: str) -> dict[str, str]:
    return {"status": "ok" if ok else "error", "reason": reason}

