from __future__ import annotations

from threading import Lock
from typing import Any


class AuditService:
    def __init__(self) -> None:
        self._lock = Lock()
        self._entries: list[dict[str, Any]] = []

    def add(self, event_type: str, request_id: str, payload: dict[str, Any]) -> None:
        item = {
            "event_type": event_type.strip() or "unknown",
            "request_id": request_id.strip(),
            "payload": dict(payload),
        }
        with self._lock:
            self._entries.append(item)

    def list_all(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(item) for item in self._entries]

    def by_request(self, request_id: str) -> list[dict[str, Any]]:
        key = request_id.strip()
        with self._lock:
            return [dict(item) for item in self._entries if item.get("request_id") == key]

    def count(self) -> int:
        with self._lock:
            return len(self._entries)

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def summary(self) -> dict[str, int]:
        with self._lock:
            out: dict[str, int] = {}
            for item in self._entries:
                t = str(item.get("event_type", "unknown"))
                out[t] = out.get(t, 0) + 1
            return out

    def latest(self) -> dict[str, Any] | None:
        with self._lock:
            if not self._entries:
                return None
            return dict(self._entries[-1])

    def contains_event(self, event_type: str) -> bool:
        target = event_type.strip()
        if not target:
            return False
        with self._lock:
            return any(item.get("event_type") == target for item in self._entries)

    def remove_by_request(self, request_id: str) -> int:
        key = request_id.strip()
        with self._lock:
            before = len(self._entries)
            self._entries = [item for item in self._entries if item.get("request_id") != key]
            return before - len(self._entries)

