from __future__ import annotations

from typing import Any


DEFAULTS = {
    "max_items": 50,
    "strict_mode": True,
    "allow_delete": False,
    "audit_level": "normal",
}


class ConfigService:
    def __init__(self) -> None:
        self._values: dict[str, Any] = dict(DEFAULTS)

    def get(self, key: str, fallback: Any = None) -> Any:
        return self._values.get(key, fallback)

    def set(self, key: str, value: Any) -> None:
        self._values[str(key)] = value

    def get_bool(self, key: str, fallback: bool) -> bool:
        raw = self.get(key, fallback)
        if isinstance(raw, bool):
            return raw
        if isinstance(raw, str):
            t = raw.strip().lower()
            if t in {"true", "1", "yes"}:
                return True
            if t in {"false", "0", "no"}:
                return False
        return fallback

    def get_int(self, key: str, fallback: int) -> int:
        raw = self.get(key, fallback)
        if isinstance(raw, bool):
            return fallback
        try:
            return int(raw)
        except Exception:
            return fallback

    def reset(self) -> None:
        self._values = dict(DEFAULTS)

    def snapshot(self) -> dict[str, Any]:
        return dict(self._values)

    def merge(self, updates: dict[str, Any]) -> None:
        for key, value in updates.items():
            self._values[str(key)] = value

    def ensure_defaults(self) -> None:
        for key, value in DEFAULTS.items():
            if key not in self._values:
                self._values[key] = value

    def validate(self) -> list[str]:
        errors: list[str] = []
        if self.get_int("max_items", 0) <= 0:
            errors.append("max_items")
        if self.get("audit_level", "") not in {"low", "normal", "high"}:
            errors.append("audit_level")
        return errors

