from __future__ import annotations

from typing import Any


class Container:
    def __init__(self) -> None:
        self._services: dict[str, Any] = {}

    def register(self, name: str, service: Any) -> None:
        key = name.strip().lower()
        if not key:
            raise ValueError("service name required")
        self._services[key] = service

    def resolve(self, name: str) -> Any:
        key = name.strip().lower()
        if not key:
            raise ValueError("service name required")
        if key not in self._services:
            raise KeyError(f"missing service: {key}")
        return self._services[key]

    def has(self, name: str) -> bool:
        key = name.strip().lower()
        return bool(key) and key in self._services

    def keys(self) -> list[str]:
        return sorted(self._services.keys())

    def snapshot(self) -> dict[str, str]:
        return {key: type(value).__name__ for key, value in self._services.items()}

    def clear(self) -> None:
        self._services.clear()

    def clone(self) -> "Container":
        other = Container()
        for key, value in self._services.items():
            other.register(key, value)
        return other

    def remove(self, name: str) -> bool:
        key = name.strip().lower()
        if not key:
            return False
        if key in self._services:
            del self._services[key]
            return True
        return False

    def count(self) -> int:
        return len(self._services)

    def require(self, names: list[str]) -> list[str]:
        missing: list[str] = []
        for name in names:
            if not self.has(name):
                missing.append(name)
        return missing

    def resolve_many(self, names: list[str]) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for name in names:
            out[name] = self.resolve(name)
        return out

