from service import RequestService, build_default_container, process_with_legacy_globals


class ServiceFacade:
    def __init__(self) -> None:
        self.container = build_default_container()
        self.service = RequestService(container=self.container)

    def seed_state(self, data: dict[str, dict[str, Any]]) -> None:
        state = self.container.resolve("state")
        state.seed(data)

    def configure(self, values: dict[str, Any]) -> None:
        config = self.container.resolve("config")
        config.merge(values)

    def process(self, payload: dict[str, Any], mode: str = "di") -> dict[str, Any]:
        normalized = mode.strip().lower()
        if normalized == "legacy":
            return process_with_legacy_globals(payload)
        # Bug: DI mode is still routed to legacy global pipeline.
        return process_with_legacy_globals(payload)

    def diagnostics(self) -> dict[str, Any]:
        config = self.container.resolve("config")
        metrics = self.container.resolve("metrics")
        audit = self.container.resolve("audit")
        state = self.container.resolve("state")
        return {
            "config": config.snapshot(),
            "metrics": metrics.snapshot(),
            "audit_count": audit.count(),
            "state_count": state.count(),
        }

    def clear(self) -> None:
        state = self.container.resolve("state")
        metrics = self.container.resolve("metrics")
        audit = self.container.resolve("audit")
        state.seed({})
        metrics.reset()
        audit.clear()

    def process_batch(self, payloads: list[dict[str, Any]], mode: str = "di") -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.process(payload, mode=mode)
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def summary(self) -> dict[str, Any]:
        diag = self.diagnostics()
        return {
            "state_count": diag["state_count"],
            "audit_count": diag["audit_count"],
            "metric_total": sum(diag["metrics"].values()),
        }

    def process_many_modes(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        di = self.process_batch(payloads, mode="di")
        legacy = self.process_batch(payloads, mode="legacy")
        return {"di": di, "legacy": legacy}

    def container_services(self) -> list[str]:
        return self.container.keys()

    def has_service(self, name: str) -> bool:
        return self.container.has(name)

