from threading import Lock


class MetricsService:
    def __init__(self) -> None:
        self._lock = Lock()
        self._values: dict[str, int] = {}

    def incr(self, key: str, amount: int = 1) -> None:
        metric = key.strip()
        if not metric:
            return
        with self._lock:
            self._values[metric] = self._values.get(metric, 0) + amount

    def get(self, key: str) -> int:
        metric = key.strip()
        if not metric:
            return 0
        with self._lock:
            return self._values.get(metric, 0)

    def snapshot(self) -> dict[str, int]:
        with self._lock:
            return dict(self._values)

    def reset(self) -> None:
        with self._lock:
            self._values.clear()

    def total(self) -> int:
        with self._lock:
            return sum(self._values.values())

    def top(self, limit: int = 5) -> list[tuple[str, int]]:
        pairs = sorted(self.snapshot().items(), key=lambda item: item[1], reverse=True)
        return pairs[: max(0, int(limit))]

    def has(self, key: str) -> bool:
        return self.get(key) > 0

    def export_lines(self) -> list[str]:
        snap = self.snapshot()
        return [f"{k}={v}" for k, v in sorted(snap.items())]

    def merge(self, other: "MetricsService") -> None:
        for key, value in other.snapshot().items():
            self.incr(key, int(value))

    def clear_key(self, key: str) -> bool:
        metric = key.strip()
        if not metric:
            return False
        snap = self.snapshot()
        if metric not in snap:
            return False
        with self._lock:
            if metric in self._values:
                del self._values[metric]
                return True
        return False

