from state_repository import StateRepository


class RequestService:
    def __init__(
        self,
        *,
        container: Container,
    ) -> None:
        self._container = container

    def _resolve(self) -> tuple[ConfigService, MetricsService, AuditService, StateRepository]:
        config = self._container.resolve("config")
        metrics = self._container.resolve("metrics")
        audit = self._container.resolve("audit")
        state = self._container.resolve("state")
        return config, metrics, audit, state

    def process(self, payload: dict[str, Any]) -> dict[str, Any]:
        config, metrics, audit, state = self._resolve()
        return handle_request(payload, config=config, metrics=metrics, audit=audit, state=state)

    def process_batch(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.process(payload)
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}


