from __future__ import annotations

from threading import Lock
from typing import Any


class StateRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._items: dict[str, dict[str, Any]] = {}

    def seed(self, records: dict[str, dict[str, Any]]) -> None:
        with self._lock:
            self._items = {str(key): dict(value) for key, value in records.items()}

    def get(self, key: str) -> dict[str, Any] | None:
        item_key = key.strip()
        if not item_key:
            return None
        with self._lock:
            item = self._items.get(item_key)
            return dict(item) if item is not None else None

    def set(self, key: str, value: dict[str, Any]) -> None:
        item_key = key.strip()
        if not item_key:
            raise ValueError("key required")
        with self._lock:
            self._items[item_key] = dict(value)

    def delete(self, key: str) -> bool:
        item_key = key.strip()
        if not item_key:
            return False
        with self._lock:
            if item_key in self._items:
                del self._items[item_key]
                return True
            return False

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._items.keys())

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(value) for key, value in self._items.items()}

    def count(self) -> int:
        with self._lock:
            return len(self._items)

    def values(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(value) for value in self._items.values()]

    def clear(self) -> None:
        with self._lock:
            self._items.clear()

    def has(self, key: str) -> bool:
        return self.get(key) is not None

