from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class RequestContext:
    request_id: str
    user_id: str
    action: str
    payload: dict[str, Any]
    tags: list[str] = field(default_factory=list)

    def validate(self) -> None:
        if not self.request_id.strip():
            raise ValueError("request_id is required")
        if not self.user_id.strip():
            raise ValueError("user_id is required")
        if not self.action.strip():
            raise ValueError("action is required")


@dataclass(frozen=True)
class ActionResult:
    ok: bool
    reason: str
    request_id: str
    action: str
    output: dict[str, Any]
    trace: list[dict[str, Any]]


def context_from_payload(payload: dict[str, Any]) -> RequestContext:
    ctx = RequestContext(
        request_id=str(payload.get("request_id", "")).strip(),
        user_id=str(payload.get("user_id", "")).strip(),
        action=str(payload.get("action", "")).strip().lower(),
        payload=dict(payload.get("payload", {}) or {}),
        tags=[str(item).strip() for item in payload.get("tags", []) if str(item).strip()],
    )
    ctx.validate()
    return ctx


def to_public(result: ActionResult) -> dict[str, Any]:
    return {
        "ok": result.ok,
        "reason": result.reason,
        "request_id": result.request_id,
        "action": result.action,
        "output": dict(result.output),
        "trace": [dict(item) for item in result.trace],
    }


def summarize_trace(trace: list[dict[str, Any]]) -> dict[str, int]:
    return {"steps": len(trace)}


def is_success(result: dict[str, Any]) -> bool:
    return bool(result.get("ok", False))

